package io.github.ericonyu.qimen4java;
import com.google.gson.Gson;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class Qimen{private static final Gson GSON=new Gson();private static volatile Path engine;private Qimen(){}private static synchronized Path engine()throws IOException{if(engine==null){engine=Files.createTempFile("qimen-engine-",".cjs");try(InputStream in=Qimen.class.getResourceAsStream("/engine.cjs")){if(in==null)throw new IOException("engine.cjs missing");Files.copy(in,engine,StandardCopyOption.REPLACE_EXISTING);}engine.toFile().deleteOnExit();}return engine;}public static Map<String,Object> calculate(Map<String,Object> input)throws IOException,InterruptedException{Process p=new ProcessBuilder("node",engine().toString()).start();try(OutputStream out=p.getOutputStream()){out.write(GSON.toJson(input).getBytes(StandardCharsets.UTF_8));}String stdout=new String(p.getInputStream().readAllBytes(),StandardCharsets.UTF_8);String stderr=new String(p.getErrorStream().readAllBytes(),StandardCharsets.UTF_8);int code=p.waitFor();Map<String,Object> env=GSON.fromJson(stdout,Map.class);if(code!=0||!Boolean.TRUE.equals(env.get("ok")))throw new IOException(String.valueOf(env.getOrDefault("error",stderr)));return (Map<String,Object>)env.get("data");}}
